ON CONFLICT (id) DO UPDATE SET
  name             = EXCLUDED.name,
  type             = EXCLUDED.type,
  width            = EXCLUDED.width,
  height           = EXCLUDED.height,
  background_color = EXCLUDED.background_color,
  elements         = EXCLUDED.elements,
  story            = EXCLUDED.story,
  updated_at       = now();

