-- Conferencia: 1 linha, 7 elementos no feed + 6 no story
SELECT id, name, jsonb_array_length(elements) AS feed_els,
       jsonb_array_length(story->'elements') AS story_els
FROM social_templates WHERE id = 'modelo-feed-story';
